// Simplified P2P three-way match check
function threeWayMatch(purchaseOrder, goodsReceipt, supplierInvoice) {
  const tolerancePct = 0.02; // 2% price tolerance

  const qtyMatch = goodsReceipt.quantity === purchaseOrder.quantity;
  const invoiceQtyOk = supplierInvoice.quantity <= goodsReceipt.quantity;

  const priceDeviation = Math.abs(
    supplierInvoice.unitPrice - purchaseOrder.unitPrice
  ) / purchaseOrder.unitPrice;
  const priceMatch = priceDeviation <= tolerancePct;

  return {
    matched: qtyMatch && invoiceQtyOk && priceMatch,
    exceptions: [
      !qtyMatch && 'QUANTITY_MISMATCH',
      !invoiceQtyOk && 'OVER_DELIVERY',
      !priceMatch && 'PRICE_DEVIATION'
    ].filter(Boolean)
  };
}

